                    if buffer.dropped > 0:
                        span.dropped_spans = buffer.dropped
                    if _should_write(buffer):
                        _flush(buffer, span)

        return sync_wrapper


def _monotonic_ns() -> int:
    """Return monotonic time in nanoseconds."""
    import time
    return time.monotonic_ns()

