        spans = [json.loads(l) for l in lines]
        by_fn = {s["function_name"]: s for s in spans}

        assert by_fn["parent"]["trace_id"] == by_fn["child"]["trace_id"]
        assert by_fn["child"]["parent_span_id"] == by_fn["parent"]["span_id"]
