            if root:
                root_of[s["span_id"]] = root
            pid = s.get("parent_span_id")
            if pid:
                children_of[pid].append(s)

    # Group key → list of matching error spans
    groups: Dict[Tuple, List[dict]] = defaultdict(list)

    for spans in by_trace.values():
        for s in spans:
