                continue
            # Check if any direct child also errored
            has_failing_child = any(
                c.get("status") == "error" for c in children_of.get(s["span_id"], [])
            )
            if has_failing_child:
                continue
            key = (
                s.get("function_name", ""),
                s.get("error_type", ""),
